roots = ['ProjectFortress/tests'] + [os.path.join('ProjectFortress',d) for d in os.listdir('ProjectFortress') if d.endswith('_tests')] + ['Library','ProjectFortress/LibraryBuiltin']
pat = re.compile(r'(?<![\w.])(\d{10,})(?![\w.])')
hits = []
for r in roots:
    for dp,_,fns in os.walk(r):
        for fn in fns:
            if not fn.endswith(('.fss','.fsi')): continue
            p=os.path.join(dp,fn)
            try: txt=open(p,encoding='utf-8',errors='replace').read()
            except Exception: continue
            for i,line in enumerate(txt.splitlines(),1):
